local ForgeBrickMaker = {}
local PRODUCTS = {
    iron_forgebrick = { name = "Železni opeka za kovaško peč", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni opeka za kovaško peč za kovace." },
    bronze_forgebrick = { name = "Bronast opeka za kovaško peč", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast opeka za kovaško peč za kovace." },
    silver_forgebrick = { name = "Srebrn opeka za kovaško peč", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn opeka za kovaško peč za kovace." },
    gilded_forgebrick = { name = "Pozlačen opeka za kovaško peč", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen opeka za kovaško peč za kovace." },
    jewel_set_forgebrick = { name = "Draguljast opeka za kovaško peč", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast opeka za kovaško peč za kovace." },
    royal_sovereign_forgebrick = { name = "Kraljevski suveren opeka za kovaško peč", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren opeka za kovaško peč z biseri za krono." },
}
local BUILDINGS = {
    forgebrick_workshop = { name = "Forgebrick delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgebrick_house = { name = "Forgebrick hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgebrick_atelier = { name = "Mojstrski forgebrick atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgebrick_palace = { name = "Suverena forgebrick palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeBrickMaker.ironStock=12; ForgeBrickMaker.bronzeStock=10; ForgeBrickMaker.woodStock=14; ForgeBrickMaker.leatherStock=8; ForgeBrickMaker.silverStock=8; ForgeBrickMaker.goldStock=6; ForgeBrickMaker.jewelStock=4; ForgeBrickMaker.pearlStock=4
ForgeBrickMaker.productStock = {}; ForgeBrickMaker.buildings = {}; ForgeBrickMaker.maker = nil; ForgeBrickMaker.activeMaking = {}; ForgeBrickMaker.totalProducts = 0; ForgeBrickMaker.dayTimer = 0
function ForgeBrickMaker.init() ForgeBrickMaker.ironStock=12; ForgeBrickMaker.bronzeStock=10; ForgeBrickMaker.woodStock=14; ForgeBrickMaker.leatherStock=8; ForgeBrickMaker.silverStock=8; ForgeBrickMaker.goldStock=6; ForgeBrickMaker.jewelStock=4; ForgeBrickMaker.pearlStock=4; ForgeBrickMaker.productStock={}; ForgeBrickMaker.buildings={}; ForgeBrickMaker.maker=nil; ForgeBrickMaker.activeMaking={}; ForgeBrickMaker.totalProducts=0; ForgeBrickMaker.dayTimer=0; print("[ForgeBrickMaker] Royal Forge Brick Maker System initialized (6 products, 4 buildings)") end
function ForgeBrickMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeBrickMaker.maker={name=n or ("Opekar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opekar najet: %s (spretnost: %d)",ForgeBrickMaker.maker.name,s),"success") end; return true end
function ForgeBrickMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeBrickMaker.build(id) local ok,e=ForgeBrickMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeBrickMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeBrickMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeBrickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeBrickMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeBrickMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeBrickMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeBrickMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeBrickMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeBrickMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeBrickMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeBrickMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeBrickMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeBrickMaker.buildings==0 then return false,"Potrebna opekarska delavnica" end; if not ForgeBrickMaker.maker then return false,"Potreben opekar" end; return true end
function ForgeBrickMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeBrickMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeBrickMaker.ironStock=ForgeBrickMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeBrickMaker.bronzeStock=ForgeBrickMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeBrickMaker.woodStock=ForgeBrickMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeBrickMaker.leatherStock=ForgeBrickMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeBrickMaker.silverStock=ForgeBrickMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeBrickMaker.goldStock=ForgeBrickMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeBrickMaker.jewelStock=ForgeBrickMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeBrickMaker.pearlStock=ForgeBrickMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeBrickMaker.maker then t=math.max(1,t-math.floor(ForgeBrickMaker.maker.skill/13)) end; table.insert(ForgeBrickMaker.activeMaking,{id="forgebrick_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeBrickMaker.completeMaking(m) local q=1.0+(ForgeBrickMaker.getQualityBonus()/100); if ForgeBrickMaker.maker then q=q+(ForgeBrickMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeBrickMaker.productStock[m.productType]=(ForgeBrickMaker.productStock[m.productType] or 0)+m.quantity; ForgeBrickMaker.totalProducts=ForgeBrickMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeBrickMaker.maker then ForgeBrickMaker.maker.itemsMade=ForgeBrickMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeBrickMaker.maker.skill=math.min(100,ForgeBrickMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opeka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgebrick.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeBrickMaker.update(dt) if not _G.state then return end; ForgeBrickMaker.dayTimer=ForgeBrickMaker.dayTimer+dt; if ForgeBrickMaker.dayTimer>=30 then ForgeBrickMaker.dayTimer=0; for i=#ForgeBrickMaker.activeMaking,1,-1 do local m=ForgeBrickMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeBrickMaker.completeMaking(m); table.remove(ForgeBrickMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeBrickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeBrickMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeBrickMaker.getStats() return {ironStock=ForgeBrickMaker.ironStock,bronzeStock=ForgeBrickMaker.bronzeStock,woodStock=ForgeBrickMaker.woodStock,leatherStock=ForgeBrickMaker.leatherStock,silverStock=ForgeBrickMaker.silverStock,goldStock=ForgeBrickMaker.goldStock,jewelStock=ForgeBrickMaker.jewelStock,pearlStock=ForgeBrickMaker.pearlStock,productStock=ForgeBrickMaker.productStock,numBuildings=#ForgeBrickMaker.buildings,hasMaker=ForgeBrickMaker.maker~=nil,makerName=ForgeBrickMaker.maker and ForgeBrickMaker.maker.name or "—",makerSkill=ForgeBrickMaker.maker and ForgeBrickMaker.maker.skill or 0,activeMaking=#ForgeBrickMaker.activeMaking,totalProducts=ForgeBrickMaker.totalProducts} end
return ForgeBrickMaker
